const nowParts = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Asia/Jakarta',
  hour: '2-digit',
  minute: '2-digit',
  hour12: false,
}).formatToParts(new Date());
const hour = nowParts.find((part) => part.type === 'hour')?.value ?? '';
const minute = nowParts.find((part) => part.type === 'minute')?.value ?? '';
const now = hour + ':' + minute;
const routes = $input.all().flatMap((item) =>
  Array.isArray(item.json) ? item.json : [item.json],
);

return routes
  .filter((route) => {
    const fallback =
      route.route_type === 'commute_to_work'
        ? '06:45'
        : route.route_type === 'commute_home'
          ? '16:45'
          : '';
    const scheduledFor = String(route.notification_time || fallback).slice(0, 5);
    return route.is_active === true && scheduledFor === now;
  })
  .map((route) => ({ json: route }));

const msg = $('Filter Incoming Message Only').first().json;
const rawChatId = msg.chatId;
const userText = msg.textRaw;
const senderName = msg.senderName;

const briefings = $('Fetch All Briefings & Routes').all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]).filter(b => b && b.route_id);
const summary = $('Fetch City Traffic Summary').first()?.json || {};
const cameras = $('Fetch Live CCTV Traffic').all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]).filter(c => c && c.camera_id);
const potholes = $('Fetch Potholes Data').all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]).filter(p => p && p.id);

const cameraLines = cameras.map(c => 
  `• ${c.road_name} (${c.camera_name}): Status *${c.traffic_status}* | ${c.vehicles_per_minute} kend/menit | Tren: ${c.trend} | Total 5 mnt: ${c.total_count} (Motor:${c.motorcycle_count}, Mobil:${c.car_count}, Bus:${c.bus_count}, Truk:${c.truck_count})`
).join('\n');

const potholeLines = potholes.map(p =>
  `• ${p.road_name}: Tingkat keparahan *${String(p.severity || '').toUpperCase()}* (Confidence: ${Math.round((p.confidence || 0)*100)}%, Status: ${p.status})`
).join('\n');

const routeLines = briefings.map(b =>
  `• Rute "${b.route_name}" (Milik: ${b.user_name}, HP: ${b.phone_number}, Jadwal: ${b.scheduled_time} WIB) -> Status: *${b.overall_status}*\n  Ringkasan Briefing:\n${b.message}`
).join('\n\n');

const systemContext = [
  `=== DATA REAL-TIME SISTEM LAJU (PALEMBANG SMART ROAD MONITORING) ===`,
  `[Ringkasan Kota]`,
  `- CCTV Aktif: ${summary.cctv_online ?? cameras.length} titik`,
  `- Total Kendaraan (5 menit terakhir): ${summary.vehicles_last_5_minutes ?? 0} kendaraan`,
  `- Titik Koridor Padat/Macet: ${summary.congested_roads ?? 0} titik`,
  `- Total Titik Jalan Berlubang Aktif: ${summary.detected_potholes ?? potholes.length} titik`,
  `- Total Rute Terdaftar: ${summary.total_routes ?? briefings.length} rute`,
  ``,
  `[Detail Pantauan Tiap Kamera CCTV Real-Time]`,
  cameraLines || 'Tidak ada data kamera.',
  ``,
  `[Detail Titik Jalan Berlubang (Potholes)]`,
  potholeLines || 'Tidak ada jalan berlubang terdeteksi.',
  ``,
  `[Daftar Rute & Briefing Keberangkatan]`,
  routeLines || 'Belum ada rute aktif.'
].join('\n');

return [{
  json: {
    chatId: rawChatId,
    senderName,
    userText,
    systemContext
  }
}];

const wh = $input.first().json;
const body = wh.body || wh;
const payload = body.payload || {};
const data = payload._data || payload.data?._data || {};

const fromMe = Boolean(payload.fromMe ?? data.id?.fromMe ?? false);
const eventName = String(payload.event || body.event || '').trim();

// Hanya izinkan persis event "message" (abaikan message.any, message.ack, session.status, dll)
if (fromMe || eventName !== 'message') {
  return [];
}

const rawChatId = payload.from || data.from || data.id?.remote || '';
const messageId = payload.id || data.id?._serialized || '';
const textRaw = String(payload.body || data.body || '').trim();
const senderName = data.notifyName || payload._data?.notifyName || 'Sobat LAJU';

if (!rawChatId || !textRaw) {
  return [];
}

return [{
  json: {
    chatId: rawChatId,
    messageId,
    textRaw,
    text: textRaw.toLowerCase(),
    senderName,
    readDelaySec: Math.floor(Math.random() * 2) + 1,
    typingDelaySec: Math.floor(Math.random() * 3) + 2
  }
}];

